-- 도커 세트 231. 여러 번 실행해도 안전하다 (NOT EXISTS 가드). 단원·display_order 는 통합 시 별도로 정한다. 원본: 02_quest_set.sql, 03_quest_set231.sql. docs/specs/spec_docker_logs_stats_set.md
INSERT INTO quest_set (id, title, description, sandbox_type, category)
SELECT 231, '도커 컨테이너 들여다보기 실습: 로그, 프로세스, 자원, 파일 복사, 변경 내역', '실행 중인 컨테이너의 로그를 줄 수·시각으로 골라 보고, 프로세스·자원 사용량을 밖에서 확인합니다. 안에서 명령을 한 번 실행하고, 파일을 꺼내고 넣고, 바뀐 파일 목록과 재시작 횟수로 이상 징후를 읽는 연습입니다.', 'docker', '도커'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest_set WHERE id = 231);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 231, 1, '컨테이너 로그 전부 저장하기', '컨테이너 `app` 이 실행 중이고 `line1` ~ `line5` 를 출력했습니다. 이 컨테이너의 **로그 전체**를 `/tmp/all.txt` 에 저장하세요.', '컨테이너가 화면에 낸 출력은 `docker logs 이름` 으로 다시 볼 수 있어요. `>` 로 파일에 저장합니다.', 'docker logs app > /tmp/all.txt
cat /tmp/all.txt

# docker logs 는 컨테이너가 남긴 표준 출력을 보여 준다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; rm -f /tmp/*.txt; docker run -d --name app alpine sh -c ''for i in 1 2 3 4 5; do echo line$i; done; sleep 3600'' >/dev/null 2>&1; sleep 1; true"]', '["sh", "-c", "( [ \\"$(cat /tmp/all.txt)\\" = \\"$(printf ''line1\\\\nline2\\\\nline3\\\\nline4\\\\nline5'')\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "5줄이 모두 있다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/all.txt)\\" = \\"$(printf ''line1\\\\nline2\\\\nline3\\\\nline4\\\\nline5'')\\" ]"]}]', '[{"title": "Docker 공식 문서: docker container logs", "url": "https://docs.docker.com/reference/cli/docker/container/logs/"}, {"title": "Docker 공식 문서: docker container stats", "url": "https://docs.docker.com/reference/cli/docker/container/stats/"}, {"title": "Docker 공식 문서: docker container cp", "url": "https://docs.docker.com/reference/cli/docker/container/cp/"}, {"title": "Docker 공식 문서: docker container diff", "url": "https://docs.docker.com/reference/cli/docker/container/diff/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 231 AND order_index = 1);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 231, 2, '끝의 몇 줄만 보기', '`app` 의 로그 중 **마지막 2줄**만 `/tmp/tail.txt` 에 저장하세요.', '로그가 길 때는 끝부분만 보면 편해요. `docker logs` 의 `--tail 숫자` 옵션을 찾아 보세요.', 'docker logs --tail 2 app > /tmp/tail.txt
cat /tmp/tail.txt

# --tail N 은 마지막 N 줄만 보여 준다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; rm -f /tmp/*.txt; docker run -d --name app alpine sh -c ''for i in 1 2 3 4 5; do echo line$i; done; sleep 3600'' >/dev/null 2>&1; sleep 1; true"]', '["sh", "-c", "( [ \\"$(cat /tmp/tail.txt)\\" = \\"$(printf ''line4\\\\nline5'')\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "마지막 두 줄만 있다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/tail.txt)\\" = \\"$(printf ''line4\\\\nline5'')\\" ]"]}]', '[{"title": "Docker 공식 문서: docker container logs", "url": "https://docs.docker.com/reference/cli/docker/container/logs/"}, {"title": "Docker 공식 문서: docker container stats", "url": "https://docs.docker.com/reference/cli/docker/container/stats/"}, {"title": "Docker 공식 문서: docker container cp", "url": "https://docs.docker.com/reference/cli/docker/container/cp/"}, {"title": "Docker 공식 문서: docker container diff", "url": "https://docs.docker.com/reference/cli/docker/container/diff/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 231 AND order_index = 2);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 231, 3, '줄마다 시각 붙이기', '`app` 의 로그를 **각 줄 앞에 시각이 붙게** 해서 `/tmp/ts.txt` 에 저장하세요. 5줄이 모두 있어야 합니다.', '`docker logs` 에는 타임스탬프를 붙이는 짧은 옵션이 있어요. `docker logs --help` 에서 time 이 들어간 줄을 찾아 보세요.', 'docker logs -t app > /tmp/ts.txt
cat /tmp/ts.txt

# -t 는 줄마다 시각(타임스탬프)을 앞에 붙인다. 언제 찍힌 로그인지 볼 때 쓴다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; rm -f /tmp/*.txt; docker run -d --name app alpine sh -c ''for i in 1 2 3 4 5; do echo line$i; done; sleep 3600'' >/dev/null 2>&1; sleep 1; true"]', '["sh", "-c", "( [ \\"$(grep -cE ''^[0-9]{4}-[0-9]{2}-[0-9]{2}T[^ ]+ line[0-9]$'' /tmp/ts.txt)\\" = 5 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "5줄이 시각으로 시작한다", "cmd": ["sh", "-c", "[ \\"$(grep -cE ''^[0-9]{4}-[0-9]{2}-[0-9]{2}T[^ ]+ line[0-9]$'' /tmp/ts.txt)\\" = 5 ]"]}]', '[{"title": "Docker 공식 문서: docker container logs", "url": "https://docs.docker.com/reference/cli/docker/container/logs/"}, {"title": "Docker 공식 문서: docker container stats", "url": "https://docs.docker.com/reference/cli/docker/container/stats/"}, {"title": "Docker 공식 문서: docker container cp", "url": "https://docs.docker.com/reference/cli/docker/container/cp/"}, {"title": "Docker 공식 문서: docker container diff", "url": "https://docs.docker.com/reference/cli/docker/container/diff/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 231 AND order_index = 3);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 231, 4, '로그를 계속 따라가며 보기', '컨테이너 `app` 이 새 로그를 계속 쓰고 있습니다. 새 줄이 생길 때마다 화면에 **이어서 보여 주는** 명령은 무엇일까요? (끝내려면 Ctrl+C)', '`tail -f` 를 써 본 적이 있다면 같은 글자를 떠올려 보세요.', NULL, NULL, '[]', 'choice', '["`docker logs --tail app`", "`docker logs -t app`", "`docker logs --live app`", "`docker logs -f app`"]', 3, '`docker logs -f`(`--follow`) 는 새 로그를 계속 따라가며 보여 줍니다. `-t` 는 시각을 붙일 뿐 따라가지 않고, `--tail` 은 뒤에 줄 수가 와야 하며 끝부분만 보여 줍니다. `--live` 는 없는 옵션이에요. 끝없이 이어지는 명령이라 채점이 필요한 실습에서는 쓰지 않습니다.', NULL, NULL, NULL, '[{"title": "Docker 공식 문서: docker container logs", "url": "https://docs.docker.com/reference/cli/docker/container/logs/"}, {"title": "Docker 공식 문서: docker container stats", "url": "https://docs.docker.com/reference/cli/docker/container/stats/"}, {"title": "Docker 공식 문서: docker container cp", "url": "https://docs.docker.com/reference/cli/docker/container/cp/"}, {"title": "Docker 공식 문서: docker container diff", "url": "https://docs.docker.com/reference/cli/docker/container/diff/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 231 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 231, 5, '컨테이너 안에서 명령 한 번 실행', '컨테이너 `box` 안에는 `/srv/greeting` 파일이 있습니다. 컨테이너 **안에서** 이 파일을 읽어 내용을 `/tmp/greeting.txt` 에 저장하세요. (이 머신의 `/srv/greeting` 이 아닙니다)', '`docker exec 컨테이너 명령` 은 실행 중인 컨테이너 안에서 명령을 한 번 실행하고 끝나요. 결과는 `>` 로 받습니다.', 'docker exec box cat /srv/greeting > /tmp/greeting.txt
cat /tmp/greeting.txt

# exec 는 이미 실행 중인 컨테이너 안에서 명령을 하나 더 돌린다. 셸이 필요 없는 한 줄 확인에 편하다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; rm -f /tmp/*.txt; docker run -d --name box alpine sh -c ''echo hello-from-box > /srv/greeting; echo ok-42 > /srv/report.txt; sleep 3600'' >/dev/null 2>&1; sleep 1; true"]', '["sh", "-c", "( [ \\"$(cat /tmp/greeting.txt)\\" = hello-from-box ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "내용이 맞다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/greeting.txt)\\" = hello-from-box ]"]}]', '[{"title": "Docker 공식 문서: docker container logs", "url": "https://docs.docker.com/reference/cli/docker/container/logs/"}, {"title": "Docker 공식 문서: docker container stats", "url": "https://docs.docker.com/reference/cli/docker/container/stats/"}, {"title": "Docker 공식 문서: docker container cp", "url": "https://docs.docker.com/reference/cli/docker/container/cp/"}, {"title": "Docker 공식 문서: docker container diff", "url": "https://docs.docker.com/reference/cli/docker/container/diff/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 231 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 231, 6, '컨테이너 안에서 도는 프로세스', '컨테이너 `app` 안에서 **어떤 프로세스가 도는지** 목록을 `/tmp/top.txt` 에 저장하세요. 안으로 들어가지 않고 밖에서 볼 수 있습니다.', '`docker top 컨테이너` 가 `ps` 처럼 목록을 보여 줘요. 제목 줄(PID 등)도 함께 나옵니다.', 'docker top app > /tmp/top.txt
cat /tmp/top.txt

# docker top 은 컨테이너의 프로세스 목록을 밖에서 보여 준다 (이 컨테이너는 sleep 3600 이 돌고 있다)', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; rm -f /tmp/*.txt; docker run -d --name app alpine sh -c ''for i in 1 2 3 4 5; do echo line$i; done; sleep 3600'' >/dev/null 2>&1; sleep 1; true"]', '["sh", "-c", "( head -1 /tmp/top.txt | grep -q PID ) && ( grep -q \\"sleep 3600\\" /tmp/top.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "제목 줄에 PID 가 있다", "cmd": ["sh", "-c", "head -1 /tmp/top.txt | grep -q PID"]}, {"label": "sleep 3600 프로세스가 보인다", "cmd": ["sh", "-c", "grep -q \\"sleep 3600\\" /tmp/top.txt"]}]', '[{"title": "Docker 공식 문서: docker container logs", "url": "https://docs.docker.com/reference/cli/docker/container/logs/"}, {"title": "Docker 공식 문서: docker container stats", "url": "https://docs.docker.com/reference/cli/docker/container/stats/"}, {"title": "Docker 공식 문서: docker container cp", "url": "https://docs.docker.com/reference/cli/docker/container/cp/"}, {"title": "Docker 공식 문서: docker container diff", "url": "https://docs.docker.com/reference/cli/docker/container/diff/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 231 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 231, 7, '호스트 파일을 컨테이너로 복사', '이 머신의 `/tmp/a.txt` 를 컨테이너 `app` 의 `/srv/a.txt` 로 **복사해 넣는** 명령입니다. 빈칸을 채우세요.', '`docker cp 원본 대상` 은 앞이 원본, 뒤가 대상이에요. 컨테이너 안 경로는 `컨테이너이름:경로` 로 씁니다.', NULL, NULL, '[]', 'fill', '["/tmp/a.txt", "app:/srv/a.txt", "app", "/srv/a.txt"]', NULL, '`docker cp 원본 대상` 에서 컨테이너 안의 경로는 `컨테이너:경로` 로 씁니다. 여기서는 원본이 이 머신의 `/tmp/a.txt`, 대상이 `app:/srv/a.txt` 입니다. 앞뒤를 바꾸면 컨테이너에서 꺼내는 복사가 돼요. `app` 만 쓰면 어느 파일인지 알 수 없고, `/srv/a.txt` 만 쓰면 이 머신의 경로로 읽힙니다.', '[0, 1]', 'docker cp {0} {1}', NULL, '[{"title": "Docker 공식 문서: docker container logs", "url": "https://docs.docker.com/reference/cli/docker/container/logs/"}, {"title": "Docker 공식 문서: docker container stats", "url": "https://docs.docker.com/reference/cli/docker/container/stats/"}, {"title": "Docker 공식 문서: docker container cp", "url": "https://docs.docker.com/reference/cli/docker/container/cp/"}, {"title": "Docker 공식 문서: docker container diff", "url": "https://docs.docker.com/reference/cli/docker/container/diff/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 231 AND order_index = 7);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 231, 8, '컨테이너 자원 사용량 한 번만 보기', '실행 중인 컨테이너 `app` 과 `web` 의 자원 사용량을 **한 번만** 출력하세요. 각 줄은 `이름: 메모리 사용량` 모양(예: `app: 400KiB / 7GiB`)으로 하고 `/tmp/mem.txt` 에 저장합니다. 숫자는 매번 달라서 모양만 확인합니다.', '`docker stats` 는 계속 갱신되니 `--no-stream` 을 붙이면 한 번만 나와요. 줄 모양은 `--format` 에 `{{.Name}}`, `{{.MemUsage}}` 를 써서 만듭니다.', 'docker stats --no-stream --format ''{{.Name}}: {{.MemUsage}}'' > /tmp/mem.txt
cat /tmp/mem.txt

# --no-stream 은 한 번만 출력하고 끝낸다. --format 으로 필요한 열만 고른다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; rm -f /tmp/*.txt; docker run -d --name app alpine sleep 3600 >/dev/null 2>&1; docker run -d --name web alpine sleep 3600 >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(wc -l < /tmp/mem.txt | tr -d '' '')\\" = 2 ] && grep -q \\"^app: \\" /tmp/mem.txt && grep -q \\"^web: \\" /tmp/mem.txt ) && ( [ \\"$(grep -cE ''^(app|web): [0-9.]+[A-Za-z]+ / [0-9.]+[A-Za-z]+$'' /tmp/mem.txt)\\" = 2 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "app 과 web 두 줄이다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/mem.txt | tr -d '' '')\\" = 2 ] && grep -q \\"^app: \\" /tmp/mem.txt && grep -q \\"^web: \\" /tmp/mem.txt"]}, {"label": "줄 모양이 이름: 사용량 / 한도 이다", "cmd": ["sh", "-c", "[ \\"$(grep -cE ''^(app|web): [0-9.]+[A-Za-z]+ / [0-9.]+[A-Za-z]+$'' /tmp/mem.txt)\\" = 2 ]"]}]', '[{"title": "Docker 공식 문서: docker container logs", "url": "https://docs.docker.com/reference/cli/docker/container/logs/"}, {"title": "Docker 공식 문서: docker container stats", "url": "https://docs.docker.com/reference/cli/docker/container/stats/"}, {"title": "Docker 공식 문서: docker container cp", "url": "https://docs.docker.com/reference/cli/docker/container/cp/"}, {"title": "Docker 공식 문서: docker container diff", "url": "https://docs.docker.com/reference/cli/docker/container/diff/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 231 AND order_index = 8);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 231, 9, '컨테이너 안의 파일 꺼내기', '컨테이너 `box` 안의 `/srv/report.txt` 를 이 머신의 `/tmp/report.txt` 로 **복사해 꺼내세요**.', '`docker cp 컨테이너:경로 이쪽경로` 처럼 컨테이너 안 경로는 `이름:경로` 로 써요. 앞이 원본, 뒤가 대상입니다.', 'docker cp box:/srv/report.txt /tmp/report.txt
cat /tmp/report.txt

# 컨테이너:경로 가 원본이면 꺼내기, 대상이면 넣기다. 컨테이너가 멈춰 있어도 복사된다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; rm -f /tmp/*.txt; docker run -d --name box alpine sh -c ''echo hello-from-box > /srv/greeting; echo ok-42 > /srv/report.txt; sleep 3600'' >/dev/null 2>&1; sleep 1; true"]', '["sh", "-c", "( [ \\"$(cat /tmp/report.txt)\\" = ok-42 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "내용이 맞다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/report.txt)\\" = ok-42 ]"]}]', '[{"title": "Docker 공식 문서: docker container logs", "url": "https://docs.docker.com/reference/cli/docker/container/logs/"}, {"title": "Docker 공식 문서: docker container stats", "url": "https://docs.docker.com/reference/cli/docker/container/stats/"}, {"title": "Docker 공식 문서: docker container cp", "url": "https://docs.docker.com/reference/cli/docker/container/cp/"}, {"title": "Docker 공식 문서: docker container diff", "url": "https://docs.docker.com/reference/cli/docker/container/diff/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 231 AND order_index = 9);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 231, 10, '컨테이너가 바꾼 파일만 골라 보기', '컨테이너 `worker` 는 시작한 뒤 파일 하나를 **새로 만들고** 하나를 **지웠습니다.** 이미지에서 달라진 것 가운데 **새로 추가된 항목(A)** 한 줄만 `/tmp/added.txt` 에 저장하세요.', '`docker diff 컨테이너` 가 변경 목록을 줘요. 앞 글자가 A(추가)·C(변경)·D(삭제)입니다. `grep` 으로 A 로 시작하는 줄만 고르세요.', 'docker diff worker
docker diff worker | grep ''^A'' > /tmp/added.txt
cat /tmp/added.txt

# docker diff 는 이미지 대비 컨테이너 파일 시스템의 변화를 A(추가) C(변경) D(삭제) 로 보여 준다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; rm -f /tmp/*.txt; docker run -d --name worker alpine sh -c ''echo x > /srv/added.txt; rm /etc/motd; sleep 3600'' >/dev/null 2>&1; sleep 1; true"]', '["sh", "-c", "( [ \\"$(cat /tmp/added.txt)\\" = \\"A /srv/added.txt\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "추가 항목 한 줄뿐이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/added.txt)\\" = \\"A /srv/added.txt\\" ]"]}]', '[{"title": "Docker 공식 문서: docker container logs", "url": "https://docs.docker.com/reference/cli/docker/container/logs/"}, {"title": "Docker 공식 문서: docker container stats", "url": "https://docs.docker.com/reference/cli/docker/container/stats/"}, {"title": "Docker 공식 문서: docker container cp", "url": "https://docs.docker.com/reference/cli/docker/container/cp/"}, {"title": "Docker 공식 문서: docker container diff", "url": "https://docs.docker.com/reference/cli/docker/container/diff/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 231 AND order_index = 10);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 231, 11, '재시작 횟수와 상태 읽기', '컨테이너 `flaky` 는 바로 종료되도록 만들어졌고 재시작 정책 때문에 몇 번 다시 떴다가 지금은 멈춰 있습니다. **상태(State.Status)** 와 **재시작 횟수(RestartCount)** 를 공백으로 이어 한 줄로 `/tmp/flaky.txt` 에 저장하세요. (예: `exited 3`)', '`docker inspect -f` 의 Go 템플릿에 `{{.State.Status}} {{.RestartCount}}` 처럼 두 값을 적을 수 있어요. 값은 눈으로 옮기지 말고 명령 출력으로 저장하세요.', 'docker inspect -f ''{{.State.Status}} {{.RestartCount}}'' flaky > /tmp/flaky.txt
cat /tmp/flaky.txt

# RestartCount 가 계속 늘어났다면 컨테이너가 반복해서 죽고 있다는 신호다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; rm -f /tmp/*.txt; docker run -d --name flaky --restart on-failure:3 alpine sh -c ''exit 1'' >/dev/null 2>&1; sleep 6; true"]', '["sh", "-c", "( [ \\"$(cat /tmp/flaky.txt)\\" = \\"$(docker inspect -f ''{{.State.Status}} {{.RestartCount}}'' flaky)\\" ] ) && ( grep -qE \\"^exited [1-9][0-9]*$\\" /tmp/flaky.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "실제 값과 같다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/flaky.txt)\\" = \\"$(docker inspect -f ''{{.State.Status}} {{.RestartCount}}'' flaky)\\" ]"]}, {"label": "상태가 exited 이고 횟수가 1 이상이다", "cmd": ["sh", "-c", "grep -qE \\"^exited [1-9][0-9]*$\\" /tmp/flaky.txt"]}]', '[{"title": "Docker 공식 문서: docker container logs", "url": "https://docs.docker.com/reference/cli/docker/container/logs/"}, {"title": "Docker 공식 문서: docker container stats", "url": "https://docs.docker.com/reference/cli/docker/container/stats/"}, {"title": "Docker 공식 문서: docker container cp", "url": "https://docs.docker.com/reference/cli/docker/container/cp/"}, {"title": "Docker 공식 문서: docker container diff", "url": "https://docs.docker.com/reference/cli/docker/container/diff/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 231 AND order_index = 11);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 231, 12, '이상한 컨테이너 들여다보는 흐름', '컨테이너 `web` 이 이상하게 동작합니다. 밖에서 안쪽 순서로 상태를 살피고 증거를 가져오는 흐름을 **앞에서 뒤**로 놓으세요.', '이름 확인 → 최근 로그 → 프로세스 → 안에서 확인 → 파일 꺼내기 순서입니다.', NULL, NULL, '[]', 'order', '["`docker ps` 로 컨테이너 이름과 실행 여부를 확인한다", "`docker logs --tail 20 web` 으로 최근 로그에서 오류를 찾는다", "`docker top web` 으로 어떤 프로세스가 도는지 본다", "`docker exec web ls /var/log` 처럼 안에서 명령을 한 번 실행해 본다", "`docker cp web:/var/log/app.log .` 로 필요한 파일을 꺼내 보관한다"]', NULL, '**목록 확인 → 최근 로그 → 프로세스 → 안에서 명령 실행 → 파일 복사** 순서입니다. 가볍고 안전한 확인(밖에서 읽기)부터 시작해 필요할 때만 안으로 들어가고, 마지막에 증거 파일을 꺼냅니다.', '[0, 1, 2, 3, 4]', NULL, NULL, '[{"title": "Docker 공식 문서: docker container logs", "url": "https://docs.docker.com/reference/cli/docker/container/logs/"}, {"title": "Docker 공식 문서: docker container stats", "url": "https://docs.docker.com/reference/cli/docker/container/stats/"}, {"title": "Docker 공식 문서: docker container cp", "url": "https://docs.docker.com/reference/cli/docker/container/cp/"}, {"title": "Docker 공식 문서: docker container diff", "url": "https://docs.docker.com/reference/cli/docker/container/diff/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 231 AND order_index = 12);

